/* Input files compiled into a benchmark image (generated by scripts/embed_files.py). */
#ifndef BM_FILES_H
#define BM_FILES_H
#include <stddef.h>
typedef struct { const char *name; const unsigned char *data; size_t size; } bm_file_t;
extern const bm_file_t bm_files[];   /* terminated by an entry with name == NULL */
extern const bm_file_t *const bm_stdin; /* NULL: empty stdin */
#endif
